// Clocked-torque G-SLIP pronk controller.
//
// Runs the SLIP-RF running template of Lu & Lin 2024 on the Corgi, with all
// four legs in phase so they reduce to a single virtual leg.
//
// The template itself is generated by the LegWheel package
// (examples/gslip/export_pronk_csv.py) and loaded here as a reference table,
// which keeps the model in one place rather than duplicating the fixed-point
// solve in C++. Each row is one 1 ms control tick and carries the reference
// pose plus a stance flag.
//
// Two impedance regimes, switched by that flag:
//   STANCE  leg-frame stiffness -- a stiff radial spring along the leg (the
//           virtual k_t the rigid linkage cannot provide) and a soft
//           tangential term, so the leg is compliant along its axis while
//           still tracking the swing.
//   FLIGHT  body-frame position tracking; the leg is unloaded and only has to
//           be repositioned for the next touchdown.
//
// The clocked torque is not optional here. A fine sweep of the model
// (LegWheel examples/gslip/corgi_stability_sweep.py) found no self-stable
// running gait for this geometry at any landing angle, stiffness or speed:
// |dP/dalpha| bottoms out around 1.15. The instability is mild -- an error
// grows ~15% per stride, doubling in about 5 strides -- so this loop has
// ample authority, but without it the gait does not persist.

#include <array>
#include <chrono>
#include <fstream>
#include <memory>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

#include <Eigen/Dense>

#include "ament_index_cpp/get_package_share_directory.hpp"
#include "rclcpp/rclcpp.hpp"
#include "corgi_msgs/msg/impedance_cmd_stamped.hpp"
#include "corgi_msgs/msg/motor_state_stamped.hpp"
#include "corgi_msgs/msg/trigger_stamped.hpp"
#include "corgi_msgs/msg/sim_leg_contact_stamped.hpp"
#include "corgi_msgs/msg/imu_stamped.hpp"

struct TemplateRow {
    double t;
    double theta;
    double beta;
    double gamma;
    bool in_stance;
};

class GslipPronkNode : public rclcpp::Node {
public:
    GslipPronkNode();
    void run();

private:
    void trigger_cb(const corgi_msgs::msg::TriggerStamped::SharedPtr msg);
    void motor_state_cb(const corgi_msgs::msg::MotorStateStamped::SharedPtr msg);
    void imu_cb(const corgi_msgs::msg::ImuStamped::SharedPtr msg);
    void contact_cb(const corgi_msgs::msg::SimLegContactStamped::SharedPtr msg);

    // Which gain regime leg i should be in for this row. With contact gating
    // off this is just row.in_stance, i.e. the historical behaviour.
    bool leg_in_stance(int leg, const TemplateRow& row) const;

    bool load_template(const std::string& path);
    void apply_row(const TemplateRow& row);
    void execute_standup_phase();
    void execute_running_phase();

    rclcpp::Publisher<corgi_msgs::msg::ImpedanceCmdStamped>::SharedPtr imp_cmd_pub_;
    rclcpp::Subscription<corgi_msgs::msg::TriggerStamped>::SharedPtr trigger_sub_;
    rclcpp::Subscription<corgi_msgs::msg::MotorStateStamped>::SharedPtr motor_state_sub_;
    rclcpp::Subscription<corgi_msgs::msg::ImuStamped>::SharedPtr imu_sub_;
    rclcpp::Subscription<corgi_msgs::msg::SimLegContactStamped>::SharedPtr contact_sub_;

    corgi_msgs::msg::ImpedanceCmdStamped imp_cmd_;
    corgi_msgs::msg::MotorStateStamped motor_state_;
    corgi_msgs::msg::ImuStamped imu_;

    // --- per-leg contact gating -------------------------------------------
    //
    // WHY. apply_row historically applied ONE row.in_stance to all four legs,
    // because the pronk reduction assumes four legs in phase collapsing to a
    // single virtual leg. Measured, they are 32-45% desynchronised, so a shared
    // schedule cannot match all four: a capture found the controller running
    // FLIGHT gains for ~71% of the time a foot was actually on the ground --
    // holding a loaded leg at ~289 N.m/rad instead of the ~36 N.m/rad virtual
    // spring the template exists to present.
    //
    // Gating the GAIN REGIME (and only that) on measured per-leg contact makes
    // the spring exist whenever the leg is really loaded. The commanded
    // trajectory stays global: theta/beta still come from the template, because
    // that is the gait. Only which stiffness matrix is applied becomes per-leg.
    //
    // !!! TRIED 2026-08-17 AND IT WRECKS THE ROBOT. DO NOT ENABLE. !!!
    //
    // The gate engaged correctly (the startup WARN fired) and the run had to be
    // aborted: legs hopping at visibly different times, then the five-bar
    // geometry inverting on several of them.
    //
    // WHY, and it is a design error not a tuning one. Gains and the reference
    // trajectory are two halves of ONE phase description, and this gates only
    // half of it:
    //
    //   leg still loaded, template in flight  -> STANCE gains (k_tangential
    //       600-900) commanded to track a fast flight swing-back. It cannot,
    //       so the error grows without bound.
    //   leg airborne, template in stance      -> stiff 12000 isotropic against
    //       a slow compression reference, snapping the leg toward a pose it
    //       should not hold.
    //
    // Before the change the command was at least SELF-consistent -- gains and
    // reference both came from row.in_stance -- and merely disagreed with
    // reality. This replaced that with a command that disagrees with ITSELF,
    // which is strictly worse. Nothing catches the result, because theta's
    // 17-160 deg range is a LINKAGE constraint that cannot be a per-joint stop
    // and so is unmodelled (see the joint-limits work).
    //
    // There is also positive feedback: each leg's stiffness follows its own
    // contact, so a leg that lands early gets soft gains early, diverges
    // further, and the legs desynchronise progressively.
    //
    // The principled version is PER-LEG PHASE, not per-leg gains: each leg runs
    // the template with its own clock, advanced by its own touchdown, so gains
    // and reference stay consistent within a leg. That is a real gait
    // scheduler, not a flag. Kept here, off by default, as the record of what
    // was tried and why it failed.
    bool contact_gated_gains_;          // off by default -- opt in
    int contact_debounce_;              // consecutive samples before switching
    double contact_timeout_s_;          // stale topic -> fall back to template
    std::array<bool, 4> leg_contact_{{false, false, false, false}};
    std::array<bool, 4> leg_contact_stable_{{false, false, false, false}};
    std::array<int, 4> leg_contact_count_{{0, 0, 0, 0}};
    double last_contact_stamp_;
    // mutable so the one-shot staleness warning can fire from the const
    // leg_in_stance(). A gate falling back silently is exactly the class of
    // fault this session kept finding.
    mutable bool contact_stale_warned_;

    // Constant rotation of the template's in_stance labels, seconds; positive
    // delays the gain switch. See load_template for the measurement and the
    // reasoning. 0.0 = shipped behaviour, bit-identical.
    double stance_label_shift_s_;

    // Fraction of the cycle the in_stance labels should span; the window is
    // resized by moving the LIFTOFF edge only, onset untouched, so it composes
    // with the shift (shift places the onset, duty sets the length). See
    // load_template. 0.0 = off, template's own labels, bit-identical.
    double stance_label_duty_;

    // beta-dot slaving (S29): scale the stance beta sweep about touchdown by
    // f = v_slave / v_design, so rolling holds at f times the template's
    // design speed. See load_template. 1.0 = off, bit-identical.
    double stance_sweep_scale_;

    std::vector<corgi_msgs::msg::ImpedanceCmd*> imp_cmd_modules_;
    std::vector<TemplateRow> template_;

    bool trigger_;
    bool sim_;

    // Stance: the virtual leg spring, split across four legs in a pronk.
    // k_radial = k_rel * m * g / l0 / 4 with k_rel = 18, at the nominal stance
    // theta = 100 deg (l0 = 0.1481 m, hip 0.2931 m) -> 8941 N/m per leg.
    //
    //   m = 30.00 kg  measured on scales
    //   m = 30.84 kg  summed from CorgiRobotABAD.proto -- agrees to 2.8%
    //
    // so one value covers both. Peak motor torque ~14 N.m, 41% of the limit.
    //
    // The nominal stance is deliberately NOT the paper's r~ = 0.6303 optimum,
    // which for this robot is a 0.230 m crouch. Standing at 0.293 m instead
    // costs only a slope penalty (1.154 -> 1.232) and buys a 26% lower peak
    // ground reaction, 41% rather than 53% torque, and a 43% softer spring --
    // the last mattering most, since a softer virtual spring is much less
    // corrupted by the 0.36-0.68 N.m joint friction. See LegWheel
    // examples/gslip/stance_height_tradeoff.py.
    //
    // Only the stiffness would change with mass anyway: since
    // k = k_rel*m*g/l0, the ratio k/m is mass-independent and the stance EOM
    // divides through by m, so the template, the fixed point (beta 74.75 deg,
    // alpha 23.75 deg) and the GRF in body weights are all identical.
    //
    // k_lateral holds the ABAD axis. It must NOT be zero: with leg_frame the
    // lateral axis is the ABAD direction, so K_joint = J^T K J would give a
    // near-zero kp_h and the hip roll would go floppy.
    //
    // Sizing it from the 0.0917 m ABAD-to-wheel-plane offset was wrong. At
    // k_lateral = 30000 the measured kp_h was 972 N.m/rad, not the ~250
    // intended, so the effective moment arm in the Jacobian is nearer 0.18 m.
    // That over-stiff ABAD fed large off-diagonal coupling torques into the
    // leg motors: applied torque peaked at 33-35 N.m against the 35 N.m limit
    // while the model predicted 14 N.m, and the leg could not reach its
    // commanded extension because it was torque-limited, not
    // stiffness-limited. 7500 N/m gives roughly the 250 N.m/rad originally
    // wanted, which held gamma to about 1 degree.
    // b_radial defaults to ZERO, and that is deliberate. The G-SLIP model is
    // conservative: the spring returns everything it stores, so any radial
    // damping is a deviation from the model rather than a refinement of it.
    // The original 72 came from a rule of thumb (0.008*k), not the physics.
    //
    // An energy audit over the hop showed why it mattered. At b_radial = 72
    // the motors did 105 W of positive work and took 99.6 W straight back out,
    // netting only 5.5 W: energy was being absorbed during extension as fast
    // as the spring released it, so the body decelerated while still in
    // contact and never lifted off. At b_radial = 0 the braking work fell to
    // 77.6 W, net rose to 27.9 W, peak vertical velocity went 1.109 -> 1.503
    // m/s and the flight phase went 4.0% -> 31.9%.
    double k_radial_;
    double k_tangential_;
    double k_lateral_;
    double b_radial_;
    double b_tangential_;
    double b_lateral_;

    // --- Commanded lateral force: steering by FORCE, not by lean ------------
    //
    // ImpedanceCmd carries fx/fy/fz straight into
    //     trq_cmd_base = J^T * force_des        (force_control.cpp:173)
    // and this controller has always sent zeros there. Populating fy is the
    // cheapest available lateral ground reaction: no k_lateral re-tune, no new
    // estimator, and M = 0 so nothing else in that expression wakes up. Note
    // force_control also builds a force_err (line 80) and never uses it, so a
    // non-zero fy does NOT close any force-feedback loop -- which matters,
    // because force_state is not trustworthy in sim.
    //
    // WHY THIS EXISTS. Camber steers by rolling the contact along a curved
    // path, and S33 measured that at 0.02% of its geometric turn. This is the
    // other route to the same turn: a lateral ground reaction and its yaw
    // moment. Same ABAD joint, different physics. S33 could not have seen it --
    // its peak |tau_h| was 3.8-7.0 N.m because the legs ACHIEVED their
    // commanded camber, so the lateral spring sat at rest and produced almost
    // no force. Lateral force needs a demand the foot must resist.
    //
    // FRAME. fy is PER-LEG, not body frame. force_control builds the leg
    // kinematics from ROS gamma (the driver un-mirrors it at
    // corgi_driver.py:514) and ROS gamma > 0 abducts OUTWARD on all four legs,
    // so +fy is outward on all four. Converting a body-frame command therefore
    // needs the left/right selector {+1,-1,-1,+1} -- the same partition as
    // roll_sign and steer_sign, and NOT dir_abad{+1,-1,+1,-1}, which is the
    // mounting mirror the driver already applies on the way out.
    //
    // SIGN. J^T maps the force the FOOT exerts on the GROUND, so pushing the
    // feet toward +y accelerates the body toward -y. f_lateral_ is declared as
    // the force on the BODY (positive = body +y = LEFT) and negated here. If it
    // pushes the wrong way, negate the parameter -- same idiom as the attitude
    // gains, and for the same reason.
    //
    // GATING. Stance only (unloaded feet just get flung), and only once
    // yaw_ref_set_ is true, which is the existing "template is actually
    // running" flag that gamma_correction already uses. Without the second
    // gate the settle phase (in_stance = true, execute_running_phase) would be
    // pushed sideways before the first stride and bias the initial condition.
    //
    // UNITS: newtons per stance leg. Torque is clamped downstream per joint
    // (leg 29.5 / ABAD 44.25), so an over-large demand saturates rather than
    // exploding -- but it will still tip the robot, so ramp it.
    //
    // f_lateral_front_only_ applies it to A,B only. All four is a pure lateral
    // push (crab, no yaw) and isolates "does the channel produce force at all".
    // Front-only adds the yaw moment and is the steering test, and is what the
    // turning-strategies paper does (forelimbs steer, hindlimbs do not).
    double f_lateral_;
    bool f_lateral_front_only_;
    double lateral_force(int leg_index, bool in_stance) const;

    // Flight: body-frame position tracking on an unloaded leg.
    //
    // These have to be STIFF, not gentle. theta = 100 deg is the touchdown
    // pose and is reached at the END of flight, so the leg must retract and
    // re-extend through the full 15.6 deg sweep in the 127 ms flight window.
    // At k_flight = 2000 it managed only 50% of the commanded excursion and
    // touched down 11 deg short, which left the spring far less compression
    // than the template assumes, weakened push-off, and killed the flight
    // phase entirely. The leg is unloaded here, so stiff tracking is cheap.
    double k_flight_;
    double b_flight_;

    int standup_ticks_;

    // --- Body attitude correction through the ABAD joints -------------------
    //
    // The clocked-torque template shapes where the LEGS go; it contains no
    // body-level feedback at all. With |dP/dalpha| ~ 1.23 the gait is
    // unstable, so a symmetric start develops an asymmetry that grows: the
    // measured pronk stayed level in roll and pitch (< 1.5 deg) but yawed
    // 14.8 deg in 10 s, driven by the right legs carrying ~50% more contact
    // time than the left. Nothing in the controller opposed it.
    //
    // The paper's TWIX gets away without this because an alternating tripod
    // is inherently yaw-symmetric. A four-legged pronk is not.
    //
    // gamma tilts the leg laterally, moving the contact point sideways, so
    // differential gamma generates the lateral ground reaction needed for
    // roll and yaw moments:
    //   roll : left legs one way, right legs the other   (A,D vs B,C)
    //   yaw  : front legs one way, rear legs the other   (A,B vs C,D)
    //
    // Gain SIGNS are not obvious from the geometry -- if a correction makes
    // things worse, negate the gain. They are parameters for that reason.
    void update_attitude(double& roll, double& pitch, double& yaw) const;
    double gamma_correction(int leg_index) const;

    // --- Open-loop Ackermann camber pair (Stage 3 mechanism demo) -----------
    //
    // A held left/right camber differential: the pair on the turn side leans
    // harder (lam_in), the outer pair follows at the apex-condition angle
    // (lam_out), both toward the turn centre -- the rolling geometry that a
    // pair of cambered wheels needs to share one turn apex. Magnitudes come
    // from ackermann_pair() offline (LegWheel cambered_return_map.py /
    // camber_roll.py --acker); NO geometry lives here.
    //
    // gamma_acker_dir_ = 0 (the default) returns literal 0.0 before touching
    // anything, so every run without the flag is bit-identical to before this
    // existed. Applied additively in apply_row next to gamma_correction, and
    // clamped by its OWN limit -- gamma_limit_ clamps only the feedback term.
    double gamma_openloop(int leg_index) const;

    // --- Steering: differential beta ----------------------------------------
    //
    // gamma above is INERT in yaw. Measured: k_yaw = 0 collapses gamma from
    // +-5 deg pinned to +-0.3 deg and leaves the heading trajectory unchanged,
    // while the correction saturates 67-78% of the time. The robot yaws right
    // at 2.3-3.6 deg/stride whatever the controller does -- and it does it in
    // the in-place hop too, where beta is identically zero, so the yaw is
    // intrinsic to the plant. That is a MISSING ACTUATOR, not a gain to tune;
    // see "The yaw problem, consolidated" in the weekly progress log for the
    // eleven candidate causes already eliminated.
    //
    // The channel added here is differential beta. The foot is a circular arc
    // of radius 0.145 m and stance is ROLLING contact, so sweeping a leg by
    // d_beta while it is down rolls that side forward by ~r*d_beta: during
    // stance the robot is a differential drive. Unequal left/right sweep yaws
    // it,
    //
    //     d_psi ~ r * (sweep_L - sweep_R) / track,    track = 0.24 m
    //
    // which for a 5 deg sweep differential predicts 0.145*0.0873/0.24 = 0.053
    // rad ~ 3.0 deg/stride -- comparable to the parasitic rate, so the channel
    // is plausibly strong enough to cancel it as a disturbance without ever
    // finding its cause.
    //
    // CAVEAT, recorded because it is easy to forget: differential rolling
    // already FAILED as an explanation of the parasitic yaw (per-stride
    // correlation -0.011, n=150). That tested whether INCIDENTAL sweep
    // differences predict the EXISTING yaw. Whether a COMMANDED differential
    // steers is a different claim, and open. The mean rates did agree
    // (predicted 3.4-4.8 vs measured 2.9-3.4 deg/stride), so the magnitude
    // scale is right. Test open-loop first.
    //
    // Two forms, because neither covers both regimes:
    //
    //   steer_offset  a per-side beta offset, applied ONLY while in stance.
    //                 Works everywhere, including the hop. It has to be
    //                 stance-gated to do anything: in the hop row.beta is
    //                 identically 0 for the whole stride, so a CONSTANT offset
    //                 is a static leg angle, not a sweep, and under a rolling
    //                 model it rolls nothing. Gated, the leg is driven to +-s
    //                 during contact and returns in flight, which is a real
    //                 differential roll of ~s per side.
    //
    //   k_steer       per-side amplitude scale, beta * (1 +- k_steer). Only
    //                 does anything where the template already sweeps, i.e.
    //                 the forward rungs. Changes fore-aft impulse as well as
    //                 yaw, so speed moves a little -- that is how a
    //                 differential drive works.
    //
    // Both default to ZERO so this is a no-op until a run asks for steering.
    // The members themselves live below gamma_limit_, so the declaration order
    // matches the constructor's initialiser list (-Wreorder).
    double steer_command() const;

    // --- Commanded turns: a ramping heading reference ------------------------
    //
    // The steering channel above holds a HEADING; turning is the same channel
    // tracking a heading that moves. yaw_ref_ is latched once after the settle
    // and then advanced by turn_rate_ every tick, so steer_command() sees a
    // rotating reference and the control law is untouched. turn_rate_ = 0 leaves
    // the reference latched and reduces this EXACTLY to the heading hold, which
    // is what keeps every result recorded before turns existed reproducible.
    //
    // Radius follows from the speed: R = v / turn_rate. At the measured
    // top-rung 0.787 m/s, R = 2.0 m wants 0.394 rad/s.
    void advance_yaw_ref(double dt);

    // Rest-length leg extension, taken from the template's maximum theta
    // (its touchdown pose, where the spring is uncompressed).
    double theta_rest_{0.0};
    bool spring_rest_reference_;

    double roll_{0.0}, pitch_{0.0}, yaw_{0.0};
    double yaw_ref_{0.0};
    bool yaw_ref_set_{false};

    double k_roll_;
    double d_roll_;
    double k_yaw_;
    double d_yaw_;
    double gamma_limit_;   // rad, clamp on the correction
    // Separate clamp on the YAW part of gamma_correction alone (rad).
    // 0 = off, code path identical to before the parameter existed. The
    // default yaw hold saturates the shared 5 deg gamma_limit_ in every
    // baseline (log s87) and contaminates gamma; a hold clamped to ~1 deg
    // CANNOT saturate into the commanded lean, and the antisymmetric
    // Menger headline cancels what it adds (log s89, C2).
    double gamma_yaw_limit_;

    // Open-loop Ackermann pair; see gamma_openloop(). All rad except dir.
    double gamma_acker_in_;
    double gamma_acker_out_;
    // +1 = inner pair RIGHT (B,C) = lean RIGHT = CW/right turn (kappa < 0);
    // -1 mirrors; 0 off. Settled empirically 2026-08-20 (log s88) and by
    // camber_roll.py's "lambda > 0 leans right" comment.
    double gamma_acker_dir_;
    double gamma_acker_limit_;  // clamp on the open-loop term alone
    int gamma_acker_ramp_ticks_;
    // Ticks since the stride loop started, for the entry ramp. Counted in
    // apply_row so the settle (yaw_ref_set_ false) never advances it.
    int acker_ramp_count_{0};

    // Steering; see the block comment above steer_command().
    double k_steer_;
    double steer_offset_;   // rad
    double steer_limit_;    // rad, clamp on the total beta perturbation
    bool steer_prepose_;
    double k_steer_yaw_;
    double d_steer_yaw_;

    // Commanded turn rate, rad/s. Positive is a LEFT turn, following
    // steer_offset's measured sense (+offset turns left) and the right-handed
    // world yaw the IMU reports.
    double turn_rate_;

    // Anti-runaway on the reference, rad. See advance_yaw_ref().
    double turn_err_limit_;

    // Ticks to hold the stance after the trigger, before the stride starts.
    // In experiment mode the same /trigger that starts this gait also deletes
    // SUPPORT_BOX, so the robot is settling onto its legs at that instant.
    // Striding through the settle would corrupt the first touchdown.
    //
    // Raised 1000 -> 2500 on 2026-08-08. 1 s was marginal: per-stride hop data
    // across eight ramp runs shows the opening strides frequently below par and
    // then recovering, and in the worst case the robot took FIVE strides
    // (~1.34 s) to start hopping at all -- 0, 0, 0, 0, 0, 3.4, 15.0, 56.2% --
    // which failed the run's validity gate outright. Even a healthy run showed
    // a one-to-two stride transient (21.4, 55.1, then 70s). The cost is ~1.5 s
    // of extra sim time per run, against a 9.57 s pass; the benefit is fewer
    // discarded runs, and the hop segment IS the gate.
    int settle_ticks_;

    // Phase 5 step 1: hold the standing pose with the STANCE (leg-frame)
    // impedance rather than the flight gains, so the virtual spring can be
    // probed by pushing the body before anything hops.
    bool hold_stance_;
};

GslipPronkNode::GslipPronkNode()
    : Node("gslip_pronk"),
      // Order here must match DECLARATION order -- the contact members are
      // declared above trigger_, and C++ initializes in declaration order
      // regardless of what this list says.
      contact_gated_gains_(false),
      contact_debounce_(3),
      contact_timeout_s_(0.25),
      last_contact_stamp_(0.0),
      contact_stale_warned_(false),
      stance_label_shift_s_(0.0),
      stance_label_duty_(0.0),
      stance_sweep_scale_(1.0),
      trigger_(false),
      sim_(false),
      k_radial_(8941.0),
      k_tangential_(900.0),
      k_lateral_(7500.0),
      b_radial_(0.0),
      b_tangential_(30.0),
      b_lateral_(60.0),
      f_lateral_(0.0),
      f_lateral_front_only_(false),
      k_flight_(12000.0),
      b_flight_(150.0),
      standup_ticks_(2000),
      // Default OFF. The reasoning is sound for the model -- l0 is the rest
      // length and l(t) is an output -- but in the robot it flipped the
      // machine: measured compression already reaches 71-75 deg, so
      // referencing from 100 deg rest gives 29 deg of compression, about
      // 492 N per leg or 6.7 body weights against the model's 3.64, and the
      // resulting push threw it over (145 deg tilt, legs folded past their
      // 17 deg limit).
      //
      // The discrepancy is not in this reference choice. It is that the robot
      // is nowhere near the fixed point the template was solved for: that
      // fixed point assumes 2.035 m/s of forward travel, and the robot is
      // essentially hopping in place. Touchdown velocity, and therefore
      // compression, are simply not the model's.
      //
      // (Initialised here, out of narrative order, because it is DECLARED
      // before the attitude gains and -Wreorder tracks declaration order.)
      spring_rest_reference_(false),
      // Gentle. At k_roll 0.6 / k_yaw 0.4 with a 12 deg clamp the correction
      // saturated -- measured gamma reached 15-17 deg -- and while it did halve
      // the yaw drift and even out the contact balance, tilting the legs that
      // far cost the vertical push: flight fell from 34% to 8.9% and the leg
      // phase correlation from 0.92-0.98 to 0.70-0.91. The authority has to
      // stay small enough not to disturb the hop it is stabilising.
      k_roll_(0.25),
      d_roll_(0.03),
      k_yaw_(0.15),
      d_yaw_(0.02),
      gamma_limit_(5.0 / 180.0 * M_PI),
      gamma_yaw_limit_(0.0),
      gamma_acker_in_(0.0),
      gamma_acker_out_(0.0),
      gamma_acker_dir_(0.0),
      // 20 deg: above the 15 deg the Stage 3 sweep tops out at, well under
      // the +-30 deg the model's u_limits allow, and far from folding a leg.
      gamma_acker_limit_(20.0 / 180.0 * M_PI),
      // 500 ms entry ramp, mirroring camber_roll.py's lean window: a step
      // into a stiff position loop at 1 kHz is a torque spike.
      gamma_acker_ramp_ticks_(500),
      k_steer_(0.0),
      steer_offset_(0.0),
      // 8 deg. Sized above the 5 deg the authority estimate calls for, so the
      // clamp does not silently cap the first experiments, but well inside the
      // sweep the template already commands (+-18 deg at the top rung) so a
      // runaway feedback term cannot fold a leg.
      steer_limit_(8.0 / 180.0 * M_PI),
      steer_prepose_(false),
      k_steer_yaw_(0.0),
      d_steer_yaw_(0.0),
      turn_rate_(0.0),
      // 90 deg. Wide enough never to bite while the loop is keeping up -- a
      // heading-hold run that is 90 deg off has already failed -- and tight
      // enough to stop the reference lapping the robot when it is not.
      turn_err_limit_(M_PI / 2.0),
      settle_ticks_(2500),
      hold_stance_(false)
{
    RCLCPP_INFO(this->get_logger(), "G-SLIP pronk controller starting");

    this->get_parameter_or("use_sim_time", sim_, false);

    const std::string default_template =
        ament_index_cpp::get_package_share_directory("corgi_force_control")
        + "/config/gslip_pronk_template.csv";
    std::string template_path =
        this->declare_parameter<std::string>("template_path", default_template);
    // Launch files pass an empty string to mean "use the installed default"
    // rather than having to repeat the share-directory lookup.
    if (template_path.empty()) template_path = default_template;

    k_radial_ = this->declare_parameter<double>("k_radial", k_radial_);
    k_tangential_ = this->declare_parameter<double>("k_tangential", k_tangential_);
    k_lateral_ = this->declare_parameter<double>("k_lateral", k_lateral_);
    b_radial_ = this->declare_parameter<double>("b_radial", b_radial_);
    b_tangential_ = this->declare_parameter<double>("b_tangential", b_tangential_);
    b_lateral_ = this->declare_parameter<double>("b_lateral", b_lateral_);
    f_lateral_ = this->declare_parameter<double>("f_lateral", f_lateral_);
    f_lateral_front_only_ =
        this->declare_parameter<bool>("f_lateral_front_only", f_lateral_front_only_);
    k_flight_ = this->declare_parameter<double>("k_flight", k_flight_);
    b_flight_ = this->declare_parameter<double>("b_flight", b_flight_);
    standup_ticks_ = this->declare_parameter<int>("standup_ticks", standup_ticks_);
    hold_stance_ = this->declare_parameter<bool>("hold_stance", hold_stance_);
    contact_gated_gains_ = this->declare_parameter<bool>(
        "contact_gated_gains", contact_gated_gains_);
    contact_debounce_ = this->declare_parameter<int>(
        "contact_debounce", contact_debounce_);
    contact_timeout_s_ = this->declare_parameter<double>(
        "contact_timeout_s", contact_timeout_s_);
    stance_label_shift_s_ = this->declare_parameter<double>(
        "stance_label_shift_s", stance_label_shift_s_);
    stance_label_duty_ = this->declare_parameter<double>(
        "stance_label_duty", stance_label_duty_);
    stance_sweep_scale_ = this->declare_parameter<double>(
        "stance_sweep_scale", stance_sweep_scale_);
    settle_ticks_ = this->declare_parameter<int>("settle_ticks", settle_ticks_);
    k_roll_ = this->declare_parameter<double>("k_roll", k_roll_);
    d_roll_ = this->declare_parameter<double>("d_roll", d_roll_);
    k_yaw_ = this->declare_parameter<double>("k_yaw", k_yaw_);
    d_yaw_ = this->declare_parameter<double>("d_yaw", d_yaw_);
    gamma_limit_ = this->declare_parameter<double>("gamma_limit", gamma_limit_);
    gamma_yaw_limit_ =
        this->declare_parameter<double>("gamma_yaw_limit", gamma_yaw_limit_);
    gamma_acker_in_ =
        this->declare_parameter<double>("gamma_acker_in", gamma_acker_in_);
    gamma_acker_out_ =
        this->declare_parameter<double>("gamma_acker_out", gamma_acker_out_);
    gamma_acker_dir_ =
        this->declare_parameter<double>("gamma_acker_dir", gamma_acker_dir_);
    gamma_acker_limit_ =
        this->declare_parameter<double>("gamma_acker_limit", gamma_acker_limit_);
    gamma_acker_ramp_ticks_ = this->declare_parameter<int>(
        "gamma_acker_ramp_ticks", gamma_acker_ramp_ticks_);
    k_steer_ = this->declare_parameter<double>("k_steer", k_steer_);
    steer_offset_ = this->declare_parameter<double>("steer_offset", steer_offset_);
    steer_limit_ = this->declare_parameter<double>("steer_limit", steer_limit_);
    steer_prepose_ = this->declare_parameter<bool>("steer_prepose", steer_prepose_);
    k_steer_yaw_ = this->declare_parameter<double>("k_steer_yaw", k_steer_yaw_);
    d_steer_yaw_ = this->declare_parameter<double>("d_steer_yaw", d_steer_yaw_);
    turn_rate_ = this->declare_parameter<double>("turn_rate", turn_rate_);
    turn_err_limit_ =
        this->declare_parameter<double>("turn_err_limit", turn_err_limit_);
    spring_rest_reference_ =
        this->declare_parameter<bool>("spring_rest_reference", spring_rest_reference_);

    if (sim_) {
        RCLCPP_INFO(this->get_logger(), "Waiting for Webots clock...");
        while (rclcpp::ok()) {
            rclcpp::spin_some(this->get_node_base_interface());
            if (this->now().seconds() > 0.0) {
                RCLCPP_INFO(this->get_logger(), "Clock synced! Sim Time: %.2f",
                            this->now().seconds());
                break;
            }
            rclcpp::sleep_for(std::chrono::milliseconds(100));
        }
    } else {
        RCLCPP_INFO(this->get_logger(), "Real hardware mode: using system wall clock.");
    }

    imp_cmd_pub_ = this->create_publisher<corgi_msgs::msg::ImpedanceCmdStamped>(
        "impedance/command", 1000);
    trigger_sub_ = this->create_subscription<corgi_msgs::msg::TriggerStamped>(
        "trigger", 1000,
        std::bind(&GslipPronkNode::trigger_cb, this, std::placeholders::_1));
    motor_state_sub_ = this->create_subscription<corgi_msgs::msg::MotorStateStamped>(
        "motor/state", 1000,
        std::bind(&GslipPronkNode::motor_state_cb, this, std::placeholders::_1));
    imu_sub_ = this->create_subscription<corgi_msgs::msg::ImuStamped>(
        "imu", 1000,
        std::bind(&GslipPronkNode::imu_cb, this, std::placeholders::_1));
    contact_sub_ = this->create_subscription<corgi_msgs::msg::SimLegContactStamped>(
        "sim/leg_contact", 1000,
        std::bind(&GslipPronkNode::contact_cb, this, std::placeholders::_1));

    if (contact_gated_gains_) {
        // Say so loudly. This changes which stiffness matrix each leg sees, so
        // a run made with it on is not comparable to the existing campaigns.
        RCLCPP_WARN(this->get_logger(),
                    "CONTACT-GATED GAINS ON (debounce %d, timeout %.2fs). "
                    "Gain regime follows measured per-leg contact, not the "
                    "template phase. Results are NOT comparable to prior runs.",
                    contact_debounce_, contact_timeout_s_);
        RCLCPP_WARN(this->get_logger(),
                    "Source is sim/leg_contact, which does not exist on "
                    "hardware; if it never arrives the gate falls back to the "
                    "template phase and says so.");
    }

    imp_cmd_modules_ = {
        &imp_cmd_.module_a,
        &imp_cmd_.module_b,
        &imp_cmd_.module_c,
        &imp_cmd_.module_d
    };

    if (!load_template(template_path)) {
        RCLCPP_FATAL(this->get_logger(),
                     "Could not load the stride template from '%s'. Generate it with "
                     "LegWheel: uv run python examples/gslip/export_pronk_csv.py",
                     template_path.c_str());
        throw std::runtime_error("missing stride template");
    }

    // The spring is uncompressed at touchdown, so the template's maximum
    // theta is the rest extension.
    theta_rest_ = template_.front().theta;
    for (const auto& row : template_) theta_rest_ = std::max(theta_rest_, row.theta);

    RCLCPP_INFO(this->get_logger(),
                "Loaded %zu template rows (%.4f s stride), k_radial=%.0f N/m per leg",
                template_.size(), template_.back().t, k_radial_);
    RCLCPP_INFO(this->get_logger(),
                "Radial reference: %s (rest theta %.2f deg)",
                spring_rest_reference_ ? "SPRING REST (constant)"
                                       : "template trajectory",
                theta_rest_ * 180.0 / M_PI);
}

void GslipPronkNode::contact_cb(
        const corgi_msgs::msg::SimLegContactStamped::SharedPtr msg) {
    const bool raw[4] = {
        msg->module_a.contact, msg->module_b.contact,
        msg->module_c.contact, msg->module_d.contact,
    };
    // Debounce. Contact chatters at touchdown, and an undebounced gate would
    // flip the commanded stiffness by 8x between consecutive control ticks --
    // which is a bigger disturbance than the mismatch being fixed.
    for (int i = 0; i < 4; i++) {
        if (raw[i] == leg_contact_[i]) {
            leg_contact_count_[i]++;
        } else {
            leg_contact_[i] = raw[i];
            leg_contact_count_[i] = 1;
        }
        if (leg_contact_count_[i] >= contact_debounce_) {
            leg_contact_stable_[i] = leg_contact_[i];
        }
    }
    last_contact_stamp_ = this->now().seconds();
}

bool GslipPronkNode::leg_in_stance(int leg, const TemplateRow& row) const {
    if (!contact_gated_gains_) {
        return row.in_stance;
    }
    // Fall back to the template if the contact topic goes stale rather than
    // freezing on the last value. A gate that silently keeps asserting a dead
    // signal is the failure mode this project keeps finding.
    const double age = this->now().seconds() - last_contact_stamp_;
    if (last_contact_stamp_ <= 0.0 || age > contact_timeout_s_) {
        if (!contact_stale_warned_) {
            contact_stale_warned_ = true;
            RCLCPP_ERROR(this->get_logger(),
                         "contact gate STALE (age %.2fs) -- falling back to the "
                         "template phase. Gains are no longer contact-gated.",
                         age);
        }
        return row.in_stance;
    }
    contact_stale_warned_ = false;
    return leg_contact_stable_[leg];
}

void GslipPronkNode::trigger_cb(const corgi_msgs::msg::TriggerStamped::SharedPtr msg) {
    trigger_ = msg->enable;
}

void GslipPronkNode::motor_state_cb(const corgi_msgs::msg::MotorStateStamped::SharedPtr msg) {
    motor_state_ = *msg;
}

void GslipPronkNode::imu_cb(const corgi_msgs::msg::ImuStamped::SharedPtr msg) {
    imu_ = *msg;
}

bool GslipPronkNode::load_template(const std::string& path) {
    std::ifstream file(path);
    if (!file.is_open()) return false;

    std::string line;
    if (!std::getline(file, line)) return false;  // header

    template_.clear();
    while (std::getline(file, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string cell;
        TemplateRow row{};
        std::vector<double> values;
        while (std::getline(ss, cell, ',')) {
            values.push_back(std::stod(cell));
        }
        if (values.size() < 5) return false;
        row.t = values[0];
        row.theta = values[1];
        row.beta = values[2];
        row.gamma = values[3];
        row.in_stance = values[4] > 0.5;
        template_.push_back(row);
    }
    // The final row is the wrap-around of the first; dropping it keeps the
    // cycle from stalling for one tick at every stride boundary.
    if (template_.size() > 1) template_.pop_back();

    // --- stance-label duty (window length) ------------------------------
    //
    // The +80 ms label shift fixed the touchdown boundary (regime ratio
    // 0.76 -> 1.30, holds in closed loop) but moved the demand peak to the
    // LIFTOFF boundary: real liftoff happens while the labels still say
    // stance, so the leg starts its fast swing under soft stance gains and
    // pays catch-up when flight gains arrive late. Measured real contact duty
    // is ~0.40 on the on-design legs against the template's ~0.43 window --
    // the window is simply longer than real stance.
    //
    // This resizes the stance window to duty * cycle by moving the LIFTOFF
    // edge only; the onset edge stays where the template (plus any shift)
    // puts it. Applied BEFORE the shift so the two parameters are orthogonal:
    // duty = window length, shift = window placement.
    //
    // Same safety shape as the shift: global, constant, label-only --
    // theta/beta/gamma untouched, no feedback path, cannot chatter.
    if (template_.size() > 1 && stance_label_duty_ > 0.0) {
        const size_t n = template_.size();
        // The labels must form exactly one contiguous circular stance
        // segment for "the liftoff edge" to be well-defined. Refuse
        // anything else rather than guess (see the analyser-gating rule).
        size_t onset = n, transitions = 0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
        }
        const size_t m_target =
            static_cast<size_t>(std::lround(stance_label_duty_ *
                                            static_cast<double>(n)));
        if (transitions != 2 || onset == n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_label_duty=%.3f REFUSED: labels have %zu "
                         "transitions (need exactly 2, one stance segment). "
                         "Labels left untouched.",
                         stance_label_duty_, transitions);
        } else if (m_target == 0 || m_target >= n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_label_duty=%.3f REFUSED: %zu of %zu rows "
                         "is not a usable window. Labels left untouched.",
                         stance_label_duty_, m_target, n);
        } else {
            size_t m_orig = 0;
            for (size_t i = 0; i < n; i++)
                if (template_[i].in_stance) m_orig++;
            for (size_t i = 0; i < n; i++)
                template_[i].in_stance = false;
            for (size_t i = 0; i < m_target; i++)
                template_[(onset + i) % n].in_stance = true;
            RCLCPP_WARN(this->get_logger(),
                        "STANCE LABEL DUTY set to %.3f (%zu of %zu rows, "
                        "template had %zu). Liftoff edge moved, onset kept; "
                        "runs are NOT comparable to unmodified campaigns.",
                        stance_label_duty_, m_target, n, m_orig);
        }
    }

    // --- stance-label phase shift --------------------------------------
    //
    // Measured (template_contact_lag.py, nine runs, three k_t settings): the
    // schedule's stance window runs ~80 ms AHEAD of actual touchdown, against
    // a ~95 ms commanded stance -- so real stance is spent almost entirely
    // under commanded flight gains (~289 N.m/rad instead of the ~36 virtual
    // spring). Offline replay says delaying the labels ~80 ms takes
    // P(spring | foot down) from 0.6x chance to ~1.6x.
    //
    // The shift rotates ONLY the in_stance labels around the cycle; theta/
    // beta/gamma are untouched, so the trajectory -- and everything reality
    // phase-locks to -- is unchanged. Shifting the whole template would shift
    // reality with it and change nothing.
    //
    // Deliberately GLOBAL and CONSTANT: the per-leg contact gate that
    // re-timed gains from live feedback wrecked the robot (chatter + per-leg
    // positive feedback + internally inconsistent commands). A constant
    // rotation cannot chatter, treats all four legs identically, and keeps
    // the command sequence identical from stride to stride.
    //
    // Positive = labels DELAYED (gains switch later in the cycle). The
    // offline payoff is an open-loop replay estimate; in closed loop the
    // phase equilibrium may partly re-establish -- which is exactly what the
    // experiment measures.
    if (template_.size() > 1 && stance_label_shift_s_ != 0.0) {
        const size_t n = template_.size();
        const double dt = template_.back().t / static_cast<double>(n - 1);
        const long k_raw = std::lround(stance_label_shift_s_ / dt);
        const size_t k = static_cast<size_t>(((k_raw % static_cast<long>(n))
                                              + static_cast<long>(n))
                                             % static_cast<long>(n));
        std::vector<bool> orig(n);
        for (size_t i = 0; i < n; i++) orig[i] = template_[i].in_stance;
        for (size_t i = 0; i < n; i++)
            template_[i].in_stance = orig[(i + n - k) % n];
        RCLCPP_WARN(this->get_logger(),
                    "STANCE LABELS SHIFTED by %+.0f ms (%zu of %zu rows). "
                    "Gain schedule is re-phased against the trajectory; runs "
                    "are NOT comparable to unshifted campaigns.",
                    stance_label_shift_s_ * 1e3, k, n);
    }

    // --- stance beta-sweep scaling (beta-dot slaving, S29's fix) ----------
    //
    // Rolling contact requires beta-dot = v_body / L(theta) at every instant
    // of stance (the foot rim's absolute angle IS beta). The template
    // satisfies this at its own design speed; the robot runs slower, so the
    // clocked beta(t) drags the feet through the ground -- the S28
    // dissipation, and the self-reinforcing "grip costs speed" loop.
    //
    // Because the template is rolling-consistent at v_design, slaving to a
    // slower v is EXACTLY a scaling of the stance sweep about touchdown:
    //   beta'(t) = beta_td + f * (beta(t) - beta_td),  f = v_slave/v_design
    // gives beta-dot' = f * v_design / L = v_slave / L. No kinematics needed.
    //
    // Flight rows get the liftoff offset blended linearly to zero so the
    // next touchdown beta is unchanged and beta is continuous at both
    // boundaries. theta, gamma, labels untouched. Same safety shape as the
    // shift and duty: global, constant, precomputed at load, no feedback
    // path, cannot chatter. 1.0 = shipped behaviour, bit-identical.
    if (template_.size() > 1 && stance_sweep_scale_ != 1.0) {
        const size_t n = template_.size();
        size_t onset = n, transitions = 0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
        }
        size_t m = 0;
        for (size_t i = 0; i < n; i++)
            if (template_[i].in_stance) m++;
        if (stance_sweep_scale_ <= 0.0 || stance_sweep_scale_ > 1.0) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_sweep_scale=%.3f REFUSED: must be in (0, 1]."
                         " Beta left untouched.", stance_sweep_scale_);
        } else if (transitions != 2 || onset == n || m == 0 || m >= n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_sweep_scale=%.3f REFUSED: labels have %zu "
                         "transitions (need exactly 2, one stance segment). "
                         "Beta left untouched.",
                         stance_sweep_scale_, transitions);
        } else {
            const double f = stance_sweep_scale_;
            const double b_td = template_[onset].beta;
            double sweep_orig = 0.0, off = 0.0;
            for (size_t k2 = 0; k2 < m; k2++) {
                const size_t idx = (onset + k2) % n;
                const double b = template_[idx].beta;
                template_[idx].beta = b_td + f * (b - b_td);
                if (k2 == m - 1) {
                    sweep_orig = b - b_td;
                    off = template_[idx].beta - b;  // (f-1)*sweep, negative
                }
            }
            const size_t nf = n - m;
            for (size_t k2 = 0; k2 < nf; k2++) {
                const size_t idx = (onset + m + k2) % n;
                const double s = static_cast<double>(k2 + 1) /
                                 static_cast<double>(nf);
                template_[idx].beta += off * (1.0 - s);
            }
            RCLCPP_WARN(this->get_logger(),
                        "STANCE SWEEP SCALED by %.3f: stance beta sweep "
                        "%.3f -> %.3f rad about touchdown, flight blended "
                        "back over %zu rows. beta-dot is now slaved to "
                        "%.0f%% of the template's design speed; runs are NOT "
                        "comparable to unscaled campaigns.",
                        f, sweep_orig, f * sweep_orig, nf, f * 100.0);
        }
    }
    return template_.size() > 1;
}

void GslipPronkNode::update_attitude(double& roll, double& pitch, double& yaw) const {
    const double x = imu_.orientation.x, y = imu_.orientation.y;
    const double z = imu_.orientation.z, w = imu_.orientation.w;
    roll = std::atan2(2.0 * (w * x + y * z), 1.0 - 2.0 * (x * x + y * y));
    pitch = std::asin(std::max(-1.0, std::min(1.0, 2.0 * (w * y - z * x))));
    yaw = std::atan2(2.0 * (w * z + x * y), 1.0 - 2.0 * (y * y + z * z));
}

double GslipPronkNode::lateral_force(int leg_index, bool in_stance) const {
    // yaw_ref_set_ is the "template is running" flag, same gate as
    // gamma_correction: keeps the settle phase clean.
    if (f_lateral_ == 0.0 || !in_stance || !yaw_ref_set_) return 0.0;

    // Module order is A=FL, B=FR, C=RR, D=RL, so the forelimbs are 0 and 1.
    if (f_lateral_front_only_ && leg_index > 1) return 0.0;

    // Body +y -> leg-frame outward. Left legs abduct toward +y, right legs
    // toward -y.
    static const double lat_sign[4] = {+1.0, -1.0, -1.0, +1.0};

    // Negated: J^T wants the force the foot puts INTO the ground.
    return -f_lateral_ * lat_sign[leg_index];
}

double GslipPronkNode::gamma_correction(int leg_index) const {
    if (!yaw_ref_set_) return 0.0;

    // Module order is A=FL, B=FR, C=RR, D=RL.
    static const double roll_sign[4] = {+1.0, -1.0, -1.0, +1.0};  // left vs right
    static const double yaw_sign[4] = {+1.0, +1.0, -1.0, -1.0};   // front vs rear

    double yaw_err = yaw_ - yaw_ref_;
    while (yaw_err > M_PI) yaw_err -= 2.0 * M_PI;
    while (yaw_err < -M_PI) yaw_err += 2.0 * M_PI;

    const double wx = imu_.angular_velocity.x;  // roll rate
    const double wz = imu_.angular_velocity.z;  // yaw rate

    double yaw_part = yaw_sign[leg_index] * (k_yaw_ * yaw_err + d_yaw_ * wz);
    if (gamma_yaw_limit_ > 0.0) {
        // Gentle hold (log s89, C2): the yaw term alone is clamped small
        // enough that it cannot saturate into a commanded lean. 0 = off,
        // identical code path to before the parameter existed.
        yaw_part = std::max(-gamma_yaw_limit_,
                            std::min(gamma_yaw_limit_, yaw_part));
    }
    const double correction =
        roll_sign[leg_index] * (k_roll_ * roll_ + d_roll_ * wx) + yaw_part;

    return std::max(-gamma_limit_, std::min(gamma_limit_, correction));
}

double GslipPronkNode::gamma_openloop(int leg_index) const {
    // Off is EXACTLY off: dir 0 adds literal 0.0 in apply_row, keeping every
    // pre-existing run bit-identical.
    if (gamma_acker_dir_ == 0.0) return 0.0;

    // Gated like gamma_correction and steer_command, and for steer_command's
    // documented reasons: a held offset during the settle twists the legs
    // against the ground and fires check_ramp's template-time fiducial early.
    if (!yaw_ref_set_) return 0.0;

    // Same left/right partition as roll_sign/steer_sign. gamma > 0 abducts
    // outward, so s * lr_sign < 0 marks the pair whose contacts move TOWARD
    // the turn centre -- the inner pair, which takes lam_in (it runs the
    // tighter circle; camber_roll.py --acker is the sign-convention source).
    static const double lr_sign[4] = {+1.0, -1.0, -1.0, +1.0};
    const double s = gamma_acker_dir_ > 0.0 ? 1.0 : -1.0;
    const double signed_unit = s * lr_sign[leg_index];
    const double mag = signed_unit < 0.0 ? gamma_acker_in_ : gamma_acker_out_;

    const double ramp =
        gamma_acker_ramp_ticks_ > 0
            ? std::min(1.0, static_cast<double>(acker_ramp_count_) /
                                gamma_acker_ramp_ticks_)
            : 1.0;

    const double u = signed_unit * mag * ramp;
    return std::max(-gamma_acker_limit_, std::min(gamma_acker_limit_, u));
}

// -> the per-side beta differential to command, in radians, already clamped.
//
// One scalar for the whole robot; apply_row multiplies it by the leg's
// left/right sign. Open-loop bias plus heading feedback, so a fixed
// steer_offset can be swept on its own (k_steer_yaw = 0) to measure the
// channel's authority before any loop is closed.
//
// yaw_ is trustworthy: it matches Supervisor ground truth to 1.17 deg over a
// whole pass, so the historic failure to hold heading was authority, not
// estimation. Guarded on yaw_ref_set_ exactly like gamma_correction -- before
// the reference is latched (i.e. during standup and the settle) there is no
// error to act on, and only the open-loop term applies.
//
// The gain SIGN is not obvious from the geometry: which way a rolling
// differential turns the body depends on the sense of beta and of the
// world-frame yaw together. Decide it from the open-loop runs and negate the
// gain if the correction makes things worse -- the same reason k_roll/k_yaw
// are parameters.
double GslipPronkNode::steer_command() const {
    // NOTHING is steered until the stride loop starts. yaw_ref_set_ is the
    // flag for that: false through standup, through the hold-for-trigger loop
    // and through the settle, true from the first template row onward.
    //
    // This gates the OPEN-LOOP offset as well as the feedback, which matters
    // for two separate reasons:
    //
    //   Physically, execute_running_phase holds the settle pose with
    //   in_stance = true, so a stance-gated offset would twist the legs against
    //   the ground for 2.5 s while the robot is settling onto them after the
    //   support box is removed -- corrupting the very touchdown the settle
    //   exists to protect.
    //
    //   For measurement, check_ramp.py recovers template time from the first
    //   non-zero COMMANDED beta. Steering during the settle fires that fiducial
    //   about 4.6 s early and silently relabels the standing settle as the hop
    //   segment. That is exactly what the first two open-loop runs did: 0.0%
    //   flight, 100% all-down, theta pinned at 97 deg -- a picture of a robot
    //   standing still, reported as a failed hop.
    if (!yaw_ref_set_) return 0.0;

    double yaw_err = yaw_ - yaw_ref_;
    while (yaw_err > M_PI) yaw_err -= 2.0 * M_PI;
    while (yaw_err < -M_PI) yaw_err += 2.0 * M_PI;

    const double wz = imu_.angular_velocity.z;  // yaw rate
    const double u = steer_offset_ + k_steer_yaw_ * yaw_err + d_steer_yaw_ * wz;

    return std::max(-steer_limit_, std::min(steer_limit_, u));
}

// Advance the commanded heading by one control tick.
//
// Called only from the stride loop, i.e. only after yaw_ref_ is latched, so
// with turn_rate_ = 0 the reference never moves and this is a no-op.
//
// Two guards, and they are guarding different things:
//
//   The WRAP keeps yaw_ref_ in the same +-pi representation as yaw_. It is not
//   what saves the control law -- steer_command() wraps the error with `while`
//   loops, so it already handles a reference that has been integrating for
//   minutes. It matters for the log line and for keeping a long run's reference
//   from drifting off into a range where the difference loses precision.
//
//   The CLAMP is the one that earns its place. The wrapped error is what the
//   loop acts on, so if the commanded rate exceeds what the channel can deliver
//   the reference walks away from the robot, the error grows past pi, wraps,
//   and the correction SIGN FLIPS -- the robot suddenly steers hard the wrong
//   way while the command looks perfectly reasonable. That is precisely the
//   regime an envelope sweep is built to visit, so it cannot be left to chance.
//   Holding the reference back at turn_err_limit_ makes an over-command
//   degrade into "turning as fast as it can" instead of into garbage, and the
//   measured-vs-commanded yaw rate in check_turn.py still reports the shortfall.
void GslipPronkNode::advance_yaw_ref(double dt) {
    if (turn_rate_ == 0.0) return;

    yaw_ref_ += turn_rate_ * dt;
    while (yaw_ref_ > M_PI) yaw_ref_ -= 2.0 * M_PI;
    while (yaw_ref_ < -M_PI) yaw_ref_ += 2.0 * M_PI;

    if (turn_err_limit_ > 0.0) {
        double err = yaw_ref_ - yaw_;
        while (err > M_PI) err -= 2.0 * M_PI;
        while (err < -M_PI) err += 2.0 * M_PI;
        if (err > turn_err_limit_) yaw_ref_ -= err - turn_err_limit_;
        else if (err < -turn_err_limit_) yaw_ref_ -= err + turn_err_limit_;
        while (yaw_ref_ > M_PI) yaw_ref_ -= 2.0 * M_PI;
        while (yaw_ref_ < -M_PI) yaw_ref_ += 2.0 * M_PI;
    }
}

void GslipPronkNode::apply_row(const TemplateRow& row) {
    update_attitude(roll_, pitch_, yaw_);

    // One tick of the open-loop camber entry ramp. Counted here, gated on
    // yaw_ref_set_, so the settle contributes nothing and the ramp starts
    // with the first stride tick.
    if (yaw_ref_set_ && acker_ramp_count_ < gamma_acker_ramp_ticks_)
        acker_ramp_count_++;

    // The radial reference is the spring's REST length, not the template's
    // compressed trajectory.
    //
    // In SLIP-RF the rest length l0 is constant and l(t) is what the dynamics
    // produce under load -- an output, not a setpoint. Feeding l(t) to an
    // impedance controller as its rest position makes the leg compress by
    // F/k on top of a trajectory that already contains the compression,
    // double-counting it. Measured: commanded theta bottomed at 84.4 deg
    // while the leg reached 71-75 deg, 10-13 deg deeper on every damping
    // setting tried.
    //
    // Holding theta at the rest value instead reproduces the model: the leg
    // compresses to 84.4 deg under load, which at 8941 N/m is 262 N per leg,
    // 1048 N total, 3.56 body weights -- against the 3.64 the fixed point
    // predicts.
    //
    // beta still follows the template: that is the clocked-torque part, the
    // leg angle the controller genuinely has to drive.
    const double theta_ref = spring_rest_reference_ ? theta_rest_ : row.theta;

    // Left/right selector, same partition as gamma_correction's roll_sign.
    // A=FL, B=FR, C=RR, D=RL.
    static const double steer_sign[4] = {+1.0, -1.0, -1.0, +1.0};

    // One steering command for the whole robot, evaluated once per tick rather
    // than per leg so all four legs act on the same yaw error.
    const double u = steer_command();

    // Where the differential is applied within the stride. Stance is the only
    // place it can do anything: the foot rolls when it is DOWN, so a sweep in
    // flight contributes nothing (the same reason peak-to-peak beta overstates
    // the rolling sweep -- the swing-back rolls nothing).
    //
    // steer_prepose additionally drives the leg the OTHER way during flight, so
    // it touches down pre-positioned at -s*u and sweeps through to +s*u. That
    // doubles the swept differential for free, at the cost of a bigger step at
    // the stance/flight boundaries. Off by default: try it only if the plain
    // gate turns out to be short on authority.
    const double gate = row.in_stance ? 1.0 : (steer_prepose_ ? -1.0 : 0.0);

    for (size_t i = 0; i < imp_cmd_modules_.size(); i++) {
        auto* cmd = imp_cmd_modules_[i];
        const double s = steer_sign[i];
        cmd->theta = theta_ref;
        cmd->beta = row.beta * (1.0 + s * k_steer_) + s * u * gate;
        cmd->gamma = row.gamma + gamma_openloop(static_cast<int>(i))
                     + gamma_correction(static_cast<int>(i));

        // fx/fz and the inertia terms stay zero, so trq_cmd_base reduces to
        // J^T * [0, fy, 0] and the rest of the law is still a pure (K, B)
        // impedance needing no contact-force estimate. See the f_lateral_
        // block above for frame, sign and gating.
        cmd->fx = 0.0;
        cmd->fy = lateral_force(static_cast<int>(i), row.in_stance);
        cmd->fz = 0.0;
        cmd->mx = 0.0; cmd->my = 0.0; cmd->mz = 0.0;

        // Per-leg gain regime. With contact_gated_gains off this is exactly
        // row.in_stance for every leg, i.e. unchanged behaviour; with it on,
        // each leg gets the spring when IT is loaded rather than when the
        // template says the virtual leg is.
        if (leg_in_stance(static_cast<int>(i), row)) {
            cmd->leg_frame = true;
            cmd->kx = k_radial_;      // along the leg: the virtual spring
            cmd->ky = k_lateral_;
            cmd->kz = k_tangential_;  // perpendicular, in the sagittal plane
            cmd->bx = b_radial_;
            cmd->by = b_lateral_;
            cmd->bz = b_tangential_;
        } else {
            cmd->leg_frame = false;
            cmd->kx = k_flight_;
            cmd->ky = k_flight_;
            cmd->kz = k_flight_;
            cmd->bx = b_flight_;
            cmd->by = b_flight_;
            cmd->bz = b_flight_;
        }
    }
    // NO per-side beta mirroring. corgi_driver already applies dir_beta
    // (+1, -1, -1, +1 for A..D from motor_config.yaml) to both the command
    // and the reported state, so the left/right mounting mirror is handled
    // there. Sending the same beta to all four legs is what makes them swing
    // the same physical direction -- which is what a pronk requires.
    //
    // exp_sim_stay does negate beta for B and C, but that is to SPLAY the
    // legs into a wide static standing stance. Applying it here double-flipped
    // the right side so it moved opposite to the left, producing a left/right
    // alternating pattern instead of a pronk: legs A and D swung +/-20 deg
    // while B and C managed only -14..+7 deg.
    //
    // steer_sign above does NOT contradict any of that, despite holding the
    // same numbers as dir_beta. dir_beta is a MOUNTING mirror the driver
    // applies on the way out; steer_sign is a left/right SELECTOR applied to a
    // deliberate perturbation, in the command convention, where equal beta
    // already means equal physical direction. The two lists coincide only
    // because A/D are the left pair and B/C the right pair in both. With
    // k_steer = steer_offset = 0 this reduces exactly to `cmd->beta =
    // row.beta`, so every result recorded before this channel existed is
    // reproducible by leaving the parameters at their defaults.
}

void GslipPronkNode::execute_standup_phase() {
    // Ramp from wherever the robot actually is, not from a hardcoded folded
    // pose. If a CSV has already stood the robot up (theta ~ 120 deg),
    // starting the ramp at 17 deg commands an immediate collapse.
    //
    // A single spin_some() is NOT enough: the subscription has not yet
    // discovered the publisher at construction time, so motor_state_ is still
    // zero-initialised and the fallback fires even though the robot is
    // standing. Wait for a real sample. Wall-clock sleep, deliberately -- this
    // must work before the sim clock is known to be running.
    const int kMaxWaitMs = 5000;
    int waited_ms = 0;
    while (rclcpp::ok() && motor_state_.module_a.theta == 0.0 && waited_ms < kMaxWaitMs) {
        rclcpp::spin_some(this->get_node_base_interface());
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        waited_ms += 10;
    }

    double theta_start = motor_state_.module_a.theta;
    double beta_start = motor_state_.module_a.beta;
    if (theta_start == 0.0) {
        theta_start = 17.0 / 180.0 * M_PI;
        beta_start = 0.0;
        RCLCPP_ERROR(this->get_logger(),
                     "No motor/state after %d ms. Assuming the folded pose, which will "
                     "COLLAPSE a standing robot. Check that the simulator is running.",
                     kMaxWaitMs);
    } else {
        RCLCPP_INFO(this->get_logger(), "Got motor/state after %d ms", waited_ms);
    }

    const TemplateRow& first = template_.front();
    RCLCPP_INFO(this->get_logger(),
                "Ramping from measured theta=%.1f deg to template theta=%.1f deg",
                theta_start * 180.0 / M_PI, first.theta * 180.0 / M_PI);

    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    for (int i = 0; i < standup_ticks_ && rclcpp::ok(); i++) {
        rclcpp::spin_some(this->get_node_base_interface());

        const double s = static_cast<double>(i) / standup_ticks_;
        TemplateRow row{};
        row.t = 0.0;
        row.theta = theta_start + s * (first.theta - theta_start);
        row.beta = beta_start + s * (first.beta - beta_start);
        row.gamma = 0.0;
        row.in_stance = false;  // soft gains while posing
        apply_row(row);

        imp_cmd_.header.stamp = this->now();
        imp_cmd_pub_->publish(imp_cmd_);

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }
}

void GslipPronkNode::execute_running_phase() {
    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    // Latch the heading to hold. Taken AFTER the settle, so the block-removal
    // transient is not baked into the reference.
    yaw_ref_set_ = false;

    // Let the robot settle onto its legs before striding. In experiment mode
    // the trigger that got us here also removed the support box.
    if (settle_ticks_ > 0) {
        RCLCPP_INFO(this->get_logger(), "Settling for %d ms before the first stride",
                    settle_ticks_);
        TemplateRow settle = template_.front();
        settle.in_stance = true;
        for (int i = 0; i < settle_ticks_ && rclcpp::ok() && trigger_; i++) {
            rclcpp::spin_some(this->get_node_base_interface());
            apply_row(settle);
            imp_cmd_.header.stamp = this->now();
            imp_cmd_pub_->publish(imp_cmd_);
            next_time = next_time + period;
            rclcpp::sleep_for(std::chrono::nanoseconds(
                std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
        }
    }

    update_attitude(roll_, pitch_, yaw_);
    yaw_ref_ = yaw_;
    yaw_ref_set_ = true;
    if (gamma_acker_dir_ != 0.0) {
        // Grep-able engagement announcement, same pattern as STANCE LABEL
        // DUTY: the harness asserts this line per run, because a camber
        // command that silently failed to engage looks exactly like "camber
        // does not curve the path" -- the one wrong answer this experiment
        // cannot afford.
        RCLCPP_WARN(this->get_logger(),
                    "ACKER CAMBER set: in=%.2f deg out=%.2f deg dir=%+.0f "
                    "(ramp %d ms, clamp %.1f deg)",
                    gamma_acker_in_ * 180.0 / M_PI,
                    gamma_acker_out_ * 180.0 / M_PI,
                    gamma_acker_dir_,
                    gamma_acker_ramp_ticks_,
                    gamma_acker_limit_ * 180.0 / M_PI);
    }
    if (gamma_yaw_limit_ > 0.0) {
        // Same grep-able engagement pattern as ACKER CAMBER: a clamp that
        // silently failed to engage looks exactly like "the floor did not
        // move". Runs are NOT comparable to unclamped campaigns.
        RCLCPP_WARN(this->get_logger(),
                    "GENTLE YAW CLAMP set: +-%.2f deg on the yaw term alone "
                    "(k_yaw=%.2f d_yaw=%.2f)",
                    gamma_yaw_limit_ * 180.0 / M_PI, k_yaw_, d_yaw_);
    }
    RCLCPP_INFO(this->get_logger(),
                // f_lateral and settle_ticks are echoed because a parameter
                // that never reaches the node looks EXACTLY like a parameter
                // that does nothing. Both were unreachable from the launch
                // file until 2026-08-17, and an entire f_lateral sweep ran at
                // 0.0 without a single sign that anything was wrong. Anything
                // an experiment varies belongs on this line.
                "Running the G-SLIP pronk template. Holding heading %.1f deg "
                "(k_roll=%.2f k_yaw=%.2f, gamma limit %.1f deg, "
                "f_lateral=%.2f N%s, settle_ticks=%d)",
                yaw_ref_ * 180.0 / M_PI, k_roll_, k_yaw_,
                gamma_limit_ * 180.0 / M_PI,
                f_lateral_,
                f_lateral_front_only_ ? " (front only)" : "",
                settle_ticks_);
    // Printed every run, so /tmp/ramp_ctl.log always records what the steering
    // channel was actually asked for. A sweep is only as good as the record of
    // which value produced which dump.
    RCLCPP_INFO(this->get_logger(),
                "Steering: k_steer=%.3f steer_offset=%.2f deg "
                "(stance-gated, prepose %s) k_steer_yaw=%.3f d_steer_yaw=%.3f "
                "limit %.1f deg",
                k_steer_, steer_offset_ * 180.0 / M_PI,
                steer_prepose_ ? "ON" : "off", k_steer_yaw_, d_steer_yaw_,
                steer_limit_ * 180.0 / M_PI);
    // Separate line, so a grep for "Turn:" over /tmp/ramp_ctl.log identifies the
    // commanded radius of a dump without re-reading the invocation.
    RCLCPP_INFO(this->get_logger(),
                "Turn: turn_rate=%.4f rad/s (%.2f deg/s), err limit %.1f deg%s",
                turn_rate_, turn_rate_ * 180.0 / M_PI,
                turn_err_limit_ * 180.0 / M_PI,
                turn_rate_ == 0.0 ? "  -- HEADING HOLD, no turn commanded" : "");
    size_t index = 0;
    size_t stride_count = 0;

    while (rclcpp::ok() && trigger_) {
        rclcpp::spin_some(this->get_node_base_interface());

        // Before apply_row, so the row is commanded against this tick's
        // reference. period is 1 ms; hard-coding the same figure here would be
        // a second place to change the tick rate.
        advance_yaw_ref(period.nanoseconds() * 1e-9);

        apply_row(template_[index]);
        imp_cmd_.header.stamp = this->now();
        imp_cmd_pub_->publish(imp_cmd_);

        index++;
        if (index >= template_.size()) {
            index = 0;
            stride_count++;
            if (stride_count % 10 == 0) {
                RCLCPP_INFO(this->get_logger(), "%zu strides", stride_count);
            }
        }

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }

    RCLCPP_INFO(this->get_logger(), "Stopped after %zu strides", stride_count);
}

void GslipPronkNode::run() {
    execute_standup_phase();

    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    RCLCPP_INFO(this->get_logger(), "Holding pose; waiting for trigger");
    while (rclcpp::ok()) {
        rclcpp::spin_some(this->get_node_base_interface());

        if (trigger_) {
            execute_running_phase();
        } else {
            TemplateRow hold = template_.front();
            hold.in_stance = hold_stance_;
            apply_row(hold);
            imp_cmd_.header.stamp = this->now();
            imp_cmd_pub_->publish(imp_cmd_);
        }

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }
}

int main(int argc, char** argv) {
    rclcpp::init(argc, argv);
    auto node = std::make_shared<GslipPronkNode>();
    node->run();
    rclcpp::shutdown();
    return 0;
}
